var i=36;var n=`036-julienne-batonnet-and-brunoise`;var a=`031`;var s={en:`Julienne, Batonnet, and Brunoise`,ua:`Жульєн, батонне та брюнуаз`};var r={short:`Julienne and batonnet are different widths of vegetable matchsticks; brunoise is a very fine dice. The cuts share a geometric sequence that teaches accuracy and predictable cooking.`,sections:[{title:`Core idea`,text:`A standard julienne is a fine matchstick, commonly about 3 × 3 × 50 mm (1/8 × 1/8 × 2 in), while batonnet is thicker, about 6 × 6 × 50 mm (1/4 × 1/4 × 2 in). Fine julienne may be around 1.5 × 1.5 mm. These are training standards, not immutable requirements for every recipe.`},{title:`Scientific / practical principles`,text:`The process is a sequence of geometric transformations: stabilize and square off the ingredient, cut lengthwise slabs, stack safely, and slice slabs into equal-width sticks. Equal thickness matters more for similar cooking times than exact length.`},{title:`How to apply it`,text:`Wash and stabilize a carrot, trim a manageable section, create a flat base, then cut slabs about 3 mm thick for julienne and cut those slabs into similar strips. Use about 6 mm dimensions for batonnet. Keep stacks low enough to control with a claw grip.`},{title:`Practical example`,text:`For a quick stir-fry, 3 mm julienne carrot and pepper strips soften quickly while remaining recognizable. Thicker batonnet potato sticks are suitable for larger fries or for cutting into small dice later.`},{title:`Common mistakes and limitations`,text:`Do not chase exact millimeters at the expense of safety. Uneven sticks brown or soften at different speeds, and excessively high stacks can slip. Size may be adjusted to the ingredient and desired outcome.`},{title:`Brunoise connection`,text:`Cut regular julienne sticks and then slice across them to make brunoise cubes, commonly about 3 mm per side in CIA training references. Batonnet is typically about 6 mm square in cross-section and can become small dice. Exact dimensions are culinary conventions rather than food-safety limits.`},{title:`Related theories`,text:`035, 037.`}]};var o={short:`Жульєн і батонне є брусочками різної товщини, а брюнуаз є дуже дрібними кубиками. Ці способи нарізання ґрунтуються на спільній геометричній послідовності та вчать точності.`,sections:[{title:`Суть`,text:`Звичайний жульєн є тонкою «сірничинкою», орієнтовно 3 × 3 × 50 мм (1/8 × 1/8 × 2 дюйми); батонне є товстішим брусочком приблизно 6 × 6 × 50 мм (1/4 × 1/4 × 2 дюйми). Тонкий жульєн може мати перетин близько 1,5 × 1,5 мм. Це навчальні стандарти, а не незмінні правила для кожного рецепта.`},{title:`Наукові та практичні принципи`,text:`Метод складається з послідовних геометричних дій: стабілізувати продукт, надати йому зручної форми, нарізати поздовжні пластини, безпечно скласти їх і перетворити на однакові смужки. Для рівномірного приготування товщина важливіша за точну довжину.`},{title:`Як застосовувати`,text:`Помийте й зафіксуйте моркву, відріжте зручний сегмент, створіть пласку основу, зробіть пластини близько 3 мм для жульєну та наріжте на смужки такої самої ширини. Для батонне беріть приблизно 6 мм. Не робіть занадто високі нестійкі стоси.`},{title:`Практичний приклад`,text:`Для швидкого обсмажування жульєн моркви та перцю завтовшки 3 мм швидко розм’якшується й зберігає виразну форму. Товстіші картопляні брусочки батонне підходять для фрі або подальшого нарізання дрібними кубиками.`},{title:`Поширені помилки й обмеження`,text:`Не намагайтеся дотримуватися міліметрів ціною безпечності. Нерівні брусочки готуються по-різному, а високі стоси ковзають. Розмір можна адаптувати до продукту й бажаного результату.`},{title:`Як отримати брюнуаз`,text:`Зробіть рівні тонкі брусочки жульєн і наріжте їх поперек на маленькі кубики брюнуаз (у навчальних матеріалах CIA зазвичай близько 3 мм). Батонне має перетин орієнтовно 6 мм і може перетворюватися на дрібні кубики. Це кулінарні стандарти, а не санітарні нормативи.`},{title:`Пов’язані теорії`,text:`035, 037.`}]};var c=[35,37];var l=`References / Джерела`;var u=[`https://theicn.org/cicn/resources/133/culinary-quick-bites-knife-skills-and-knife-safety/109570/culinary-quick-bites-knife-skills-basic-knife-cuts.pdf`,`https://hr.uky.edu/work-life-and-well-being/nutrition/food-preparation/knife-skills`];var m={id:36,slug:n,group:`031`,title:s,en:r,ua:o,related:c,referenceTitle:l,references:u};export{m as default,r as en,a as group,i as id,l as referenceTitle,u as references,c as related,n as slug,s as title,o as ua};